import OpenAPIRuntime
import XCTest

@testable import Zoonk

final class TodayDecodingTests: XCTestCase {
  func testAnExamGoalsTodayDecodes() throws {
    let today = try anaTodayView()

    XCTAssertEqual(today.goal.kind, .exam)
    XCTAssertEqual(today.session.blocks.count, 8)
    XCTAssertEqual(today.planChange?.status, "proposed")
  }

  func testTheWeekCountsEveryDayStudiedOfItsStudyDays() throws {
    let week = try anaTodayView().session.week

    XCTAssertEqual(week.daysStudied, 3)
    XCTAssertEqual(week.studyDayCount, 7)
  }

  func testTheWeeksNumbersWrapOnlyBetweenWholeValues() {
    let line = TodayWeekSection.numbers(
      days: "4 of 7 days", time: (studied: "2 hrs 14 min", planned: "5 hrs 13 min"))

    XCTAssertEqual(
      line,
      "4\u{A0}of\u{A0}7\u{A0}days · 2\u{A0}hrs\u{A0}14\u{A0}min / 5\u{A0}hrs\u{A0}13\u{A0}min")
  }

  func testAMissionToFinishAChapterSaysTheLessonsAfterItsNext() throws {
    let today = try anaTodayView()
    let mission = try XCTUnwrap(today.session.missions.first { $0.kind == .finishChapter })
    let block = today.session.blocks.first { mission.opens($0) }

    XCTAssertEqual(mission.step(block: block), "Porcentagem e descontos (+1 lesson)")
  }

  func testAMissionOpeningABlockWithoutATitleNamesTheBlock() throws {
    let today = try anaTodayView()
    let practice = try XCTUnwrap(today.session.blocks.first { $0.mistakesOnly })
    let mission = try JSONDecoder().decode(
      StudyMission.self,
      from: Data(#"{"done":0,"kind":"practice","minutes":3,"status":"todo","total":1}"#.utf8))

    XCTAssertEqual(mission.step(block: practice), "Practice mistakes")
    XCTAssertNil(mission.step(block: nil))
  }

  func testAProposalSaysWhatItLeavesOutAndTheTopicsNotWrittenYet() throws {
    let text = try XCTUnwrap(planLessonsEffectText(anaTodayView().planChange?.effect))

    XCTAssertTrue(
      text.hasPrefix(
        "Leaves out 256 lessons, such as Compatibilidade da proposta de intervenção, Limites da analogia histórica"
      ), text)
    XCTAssertTrue(
      text.contains("Lessons not written yet: Conhecer as cinco competências da redação (about 5)"),
      text)
  }

  private func anaTodayView() throws -> TodayView {
    let generated = try decoder().decode(
      Components.Schemas.Today.self, from: Data(anaToday.utf8))
    return try StudyJSON.recode(generated)
  }

  private func decoder() -> JSONDecoder {
    let decoder = JSONDecoder()
    decoder.dateDecodingStrategy = .custom { decoder in
      let text = try decoder.singleValueContainer().decode(String.self)
      let style = Date.ISO8601FormatStyle(includingFractionalSeconds: true)

      guard let date = try? style.parse(text) ?? Date.ISO8601FormatStyle().parse(text) else {
        throw DecodingError.dataCorrupted(
          .init(codingPath: decoder.codingPath, debugDescription: "Not an instant: \(text)"))
      }

      return date
    }
    return decoder
  }
}

